<?php
if (!defined('ABSPATH')) exit;
final class Zica_Posts_REST {
 private $auth;private $discovery;private $outbox;private $cards;
 public function __construct($auth,$discovery,$outbox,$cards){$this->auth=$auth;$this->discovery=$discovery;$this->outbox=$outbox;$this->cards=$cards;add_action('rest_api_init',array($this,'register'));}
 public function register(){$this->register_namespace('zica-posts/v1',true);$this->register_namespace('zica-ai/v1',true);$this->register_namespace('cfrdm/v1',false);}
 private function register_namespace($ns,$full){register_rest_route($ns,'/version',array('methods'=>'GET','callback'=>array($this,'version'),'permission_callback'=>'__return_true'));register_rest_route($ns,'/health',array('methods'=>'GET','callback'=>array($this,'health'),'permission_callback'=>'__return_true'));register_rest_route($ns,'/test',array('methods'=>'GET','callback'=>array($this,'test'),'permission_callback'=>array($this->auth,'verify_api_key')));if(!$full)return;register_rest_route($ns,'/status',array('methods'=>'GET','callback'=>array($this,'status'),'permission_callback'=>array($this->auth,'verify_api_key')));register_rest_route($ns,'/sync',array('methods'=>'POST','callback'=>array($this,'sync'),'permission_callback'=>array($this->auth,'verify_api_key')));register_rest_route($ns,'/hub/sync',array('methods'=>'POST','callback'=>array($this,'hub_sync'),'permission_callback'=>array($this->auth,'verify_hmac')));register_rest_route($ns,'/hub/config',array('methods'=>'POST','callback'=>array($this,'hub_config'),'permission_callback'=>array($this->auth,'verify_api_key')));register_rest_route($ns,'/files',array('methods'=>'GET','callback'=>array($this,'files'),'permission_callback'=>array($this->auth,'verify_api_key')));register_rest_route($ns,'/outbox',array('methods'=>'GET','callback'=>array($this,'outbox'),'permission_callback'=>array($this->auth,'verify_api_key')));register_rest_route($ns,'/indexnow/batch',array('methods'=>'POST','callback'=>array($this,'indexnow_batch'),'permission_callback'=>array($this->auth,'verify_api_key')));register_rest_route($ns,'/cards/settings',array(array('methods'=>'GET','callback'=>array($this,'cards_settings'),'permission_callback'=>array($this->auth,'verify_api_key')),array('methods'=>'POST','callback'=>array($this,'cards_settings_update'),'permission_callback'=>array($this->auth,'verify_api_key'))));register_rest_route($ns,'/articles',array(array('methods'=>'GET','callback'=>array($this,'articles'),'permission_callback'=>array($this->auth,'verify_api_key')),array('methods'=>'POST','callback'=>array($this,'create_article'),'permission_callback'=>array($this->auth,'verify_api_key'))));register_rest_route($ns,'/articles/(?P<id>\d+)',array('methods'=>'GET','callback'=>array($this,'article'),'permission_callback'=>array($this->auth,'verify_api_key')));register_rest_route($ns,'/media',array('methods'=>'POST','callback'=>array($this,'media'),'permission_callback'=>array($this->auth,'verify_api_key')));}
 public function version(){return rest_ensure_response(array('success'=>true,'software_id'=>ZICA_POSTS_SOFTWARE_ID,'name'=>'Zica Posts','brand'=>'Zica.ai','version'=>ZICA_POSTS_VERSION,'api'=>'zica-posts/v1','features'=>array('modular_light_agent'=>true,'outbox'=>true,'hmac'=>true,'replay_protection'=>true,'idempotency'=>true,'anti_echo_hub_sync'=>true,'hub_webhook'=>true,'delegated_indexing'=>true,'indexnow_batch'=>true,'llms_txt'=>true,'llms_full_txt'=>true,'ai_txt'=>true,'dynamic_sitemap'=>true,'schema'=>true,'automatic_cards'=>true,'daily_1500_sao_paulo'=>true,'physical_file_fallback'=>true)));}
 public function health(){return rest_ensure_response(array('success'=>true,'software_id'=>ZICA_POSTS_SOFTWARE_ID,'version'=>ZICA_POSTS_VERSION,'site'=>home_url('/'),'timezone_job'=>ZICA_POSTS_TZ,'timestamp'=>current_time('c')));}
 public function test(){return rest_ensure_response(array('success'=>true,'message'=>'Zica Posts conectado.','version'=>ZICA_POSTS_VERSION,'site'=>array('name'=>get_bloginfo('name'),'url'=>home_url('/'),'version'=>ZICA_POSTS_VERSION,'wordpress'=>get_bloginfo('version'),'php'=>PHP_VERSION)));}
 private function next_daily_local(){$next=wp_next_scheduled(ZICA_POSTS_CRON_DAILY);if(!$next)return null;return(new DateTimeImmutable('@'.$next))->setTimezone(new DateTimeZone(ZICA_POSTS_TZ))->format(DateTime::ATOM);}
 public function status(){return rest_ensure_response(array('success'=>true,'software_id'=>ZICA_POSTS_SOFTWARE_ID,'version'=>ZICA_POSTS_VERSION,'next_daily_sync'=>$this->next_daily_local(),'daily_rule'=>'15:00 America/Sao_Paulo','last_sync'=>get_option('zica_posts_last_sync',null),'last_indexnow'=>get_option('zica_posts_last_indexnow',null),'files'=>get_option('zica_posts_discovery_files_status',array()),'outbox'=>$this->outbox->counts(),'hub'=>array('enabled'=>'1'===(string)get_option('zica_posts_hub_enabled','0'),'configured'=>(bool)get_option('zica_posts_hub_webhook_url',''),'delegates_indexing'=>'1'===(string)get_option('zica_posts_hub_delegates_indexing','1')),'cards'=>$this->cards->settings(),'readiness'=>array('search_visibility'=>'1'===(string)get_option('blog_public','1'),'wp_cron_disabled'=>defined('DISABLE_WP_CRON')&&DISABLE_WP_CRON,'root_writable'=>is_writable(ABSPATH))));}
 public function sync($request){$ids=$request->get_param('post_ids');$ids=is_array($ids)?array_values(array_unique(array_map('absint',$ids))):array();if(!$ids)$ids=get_posts(array('post_type'=>array('post','page'),'post_status'=>'publish','posts_per_page'=>500,'orderby'=>'modified','order'=>'DESC','fields'=>'ids'));foreach($ids as $id)$this->outbox->enqueue($id,'api_sync');$result=$this->outbox->process();return rest_ensure_response(array('success'=>true,'queued'=>count($ids),'result'=>$result));}
 public function files(){return rest_ensure_response(array('success'=>true,'files'=>get_option('zica_posts_discovery_files_status',array()),'manifest'=>$this->discovery->manifest_data()));}
 public function outbox($request){$limit=absint($request->get_param('limit'));return rest_ensure_response(array('success'=>true,'counts'=>$this->outbox->counts(),'events'=>$this->outbox->recent($limit?:50)));}
 public function hub_config($request){$p=$request->get_json_params();$p=is_array($p)?$p:array();if(array_key_exists('webhook_url',$p)){$url=esc_url_raw((string)$p['webhook_url']);if($url&&!$this->auth->hub_url_is_safe($url))return new WP_Error('zica_hub_url_invalid','Webhook Hub deve usar HTTPS público.',array('status'=>400));update_option('zica_posts_hub_webhook_url',$url,false);}if(array_key_exists('enabled',$p))update_option('zica_posts_hub_enabled',!empty($p['enabled'])?'1':'0',false);if(array_key_exists('delegates_indexing',$p))update_option('zica_posts_hub_delegates_indexing',!empty($p['delegates_indexing'])?'1':'0',false);if(array_key_exists('delegates_discovery',$p))update_option('zica_posts_hub_delegates_discovery',!empty($p['delegates_discovery'])?'1':'0',false);$rotated=!empty($p['rotate_secret'])?$this->auth->rotate_hub_secret():null;return rest_ensure_response(array('success'=>true,'enabled'=>'1'===(string)get_option('zica_posts_hub_enabled','0'),'webhook_url'=>get_option('zica_posts_hub_webhook_url',''),'delegates_indexing'=>'1'===(string)get_option('zica_posts_hub_delegates_indexing','1'),'delegates_discovery'=>'1'===(string)get_option('zica_posts_hub_delegates_discovery','0'),'hub_secret'=>$rotated));}
 public function indexnow_batch($request){$p=$request->get_json_params();$urls=is_array($p)&&!empty($p['urls'])&&is_array($p['urls'])?$p['urls']:array();$safe=array();$host=wp_parse_url(home_url('/'),PHP_URL_HOST);foreach($urls as $url){$url=esc_url_raw($url);if($url&&wp_parse_url($url,PHP_URL_HOST)===$host)$safe[]=$url;}return rest_ensure_response(array('success'=>true,'result'=>$this->discovery->submit_indexnow_batch($safe,500)));}
 public function cards_settings(){return rest_ensure_response(array_merge(array('success'=>true),$this->cards->settings()));}
 public function cards_settings_update($request){$position=sanitize_key((string)$request->get_param('position'));$allowed=array('before_content','after_p2','after_p4','after_content','disabled');if($position&&in_array($position,$allowed,true))update_option('zica_posts_cards_position',$position,false);$count=absint($request->get_param('count'));if($count>=1&&$count<=6)update_option('zica_posts_cards_count',$count,false);return $this->cards_settings();}
 public function articles($request){$page=max(1,absint($request->get_param('page')));$per=max(1,min(100,absint($request->get_param('per_page'))?:20));$q=new WP_Query(array('post_type'=>array('post','page'),'post_status'=>array('publish','draft','pending','future'),'paged'=>$page,'posts_per_page'=>$per,'orderby'=>'modified','order'=>'DESC'));$items=array();foreach($q->posts as $post)$items[]=array('id'=>$post->ID,'title'=>$post->post_title,'status'=>$post->post_status,'type'=>$post->post_type,'link'=>get_permalink($post->ID),'modified'=>get_the_modified_date('c',$post));return rest_ensure_response(array('success'=>true,'data'=>$items,'total'=>(int)$q->found_posts,'pages'=>(int)$q->max_num_pages));}
 public function article($request){$post=get_post(absint($request['id']));if(!$post instanceof WP_Post)return new WP_Error('zica_post_not_found','Conteúdo não encontrado.',array('status'=>404));return rest_ensure_response(array('success'=>true,'data'=>array('id'=>$post->ID,'type'=>$post->post_type,'status'=>$post->post_status,'title'=>$post->post_title,'content'=>$post->post_content,'excerpt'=>$post->post_excerpt,'slug'=>$post->post_name,'link'=>get_permalink($post->ID),'modified_gmt'=>$post->post_modified_gmt,'content_hash'=>$this->outbox->content_hash($post),'schema_json'=>get_post_meta($post->ID,'_zica_posts_json_ld',true),'featured_image_url'=>get_the_post_thumbnail_url($post->ID,'full'))));}
 private function resolve_terms($values,$taxonomy){$ids=array();foreach((array)$values as $value){if(is_numeric($value)){$ids[]=absint($value);continue;}$name=sanitize_text_field($value);if(!$name)continue;$term=term_exists($name,$taxonomy);if(!$term)$term=wp_insert_term($name,$taxonomy);if(!is_wp_error($term))$ids[]=is_array($term)?absint($term['term_id']):absint($term);}return array_values(array_unique(array_filter($ids)));}
 public function create_article($request){$p=$request->get_json_params();$p=is_array($p)?$p:array();$title=sanitize_text_field(isset($p['title'])?$p['title']:'');$content=wp_kses_post(isset($p['content'])?$p['content']:'');if(!$title||!$content)return new WP_Error('zica_posts_invalid_article','Título e conteúdo são obrigatórios.',array('status'=>400));$external_id=sanitize_text_field(isset($p['zica_ai_id'])?$p['zica_ai_id']:(isset($p['cfrdm_id'])?$p['cfrdm_id']:''));$existing=0;if($external_id){$found=get_posts(array('post_type'=>'post','post_status'=>'any','meta_key'=>'_zica_posts_external_id','meta_value'=>$external_id,'posts_per_page'=>1,'fields'=>'ids'));if($found)$existing=(int)$found[0];}$status=isset($p['status'])&&in_array($p['status'],array('publish','draft','pending','future'),true)?$p['status']:'publish';$postarr=array('post_type'=>'post','post_status'=>$status,'post_title'=>$title,'post_content'=>$content,'post_excerpt'=>sanitize_textarea_field(isset($p['excerpt'])?$p['excerpt']:''),'post_name'=>sanitize_title(isset($p['slug'])?$p['slug']:$title));if($existing)$postarr['ID']=$existing;Zica_Posts_Outbox::suppress(true);$id=wp_insert_post($postarr,true);Zica_Posts_Outbox::suppress(false);if(is_wp_error($id))return $id;if($external_id)update_post_meta($id,'_zica_posts_external_id',$external_id);if(!empty($p['json_ld_schemas'])&&is_array($p['json_ld_schemas']))update_post_meta($id,'_zica_posts_json_ld',$p['json_ld_schemas']);if(!empty($p['categories']))wp_set_post_categories($id,$this->resolve_terms($p['categories'],'category'));if(!empty($p['tags']))wp_set_post_terms($id,$this->resolve_terms($p['tags'],'post_tag'),'post_tag',false);if(!empty($p['featured_image_id']))set_post_thumbnail($id,absint($p['featured_image_id']));update_post_meta($id,'_zica_posts_last_correlation_id',sanitize_text_field((string)$request->get_header('X-Zica-Correlation-ID')));update_post_meta($id,'_zica_posts_last_inbound_hash',$this->outbox->content_hash(get_post($id)));$this->discovery->schedule_refresh(5);return rest_ensure_response(array('success'=>true,'duplicate'=>(bool)$existing,'data'=>array('id'=>$id,'link'=>get_permalink($id),'status'=>get_post_status($id))));}
 public function hub_sync($request){$p=$request->get_json_params();$p=is_array($p)?$p:array();$hash=sanitize_text_field(isset($p['content_hash'])?$p['content_hash']:'');$correlation=sanitize_text_field((string)$request->get_header('X-Zica-Correlation-ID'));if(!$correlation)$correlation=sanitize_text_field(isset($p['correlation_id'])?$p['correlation_id']:wp_generate_uuid4());$post_id=absint(isset($p['post_id'])?$p['post_id']:0);if($post_id&&$hash&&hash_equals((string)get_post_meta($post_id,'_zica_posts_last_inbound_hash',true),$hash))return rest_ensure_response(array('success'=>true,'idempotent'=>true,'post_id'=>$post_id,'correlation_id'=>$correlation));$title=sanitize_text_field(isset($p['title'])?$p['title']:'');$content=wp_kses_post(isset($p['content'])?$p['content']:'');if(!$title||!$content)return new WP_Error('zica_hub_invalid','Título e conteúdo são obrigatórios.',array('status'=>400));$arr=array('post_type'=>'post','post_status'=>'publish','post_title'=>$title,'post_content'=>$content,'post_excerpt'=>sanitize_textarea_field(isset($p['excerpt'])?$p['excerpt']:''),'post_name'=>sanitize_title(isset($p['slug'])?$p['slug']:$title));if($post_id)$arr['ID']=$post_id;Zica_Posts_Outbox::suppress(true);$saved=wp_insert_post($arr,true);Zica_Posts_Outbox::suppress(false);if(is_wp_error($saved))return $saved;if(!$hash)$hash=$this->outbox->content_hash(get_post($saved));update_post_meta($saved,'_zica_posts_last_inbound_hash',$hash);update_post_meta($saved,'_zica_posts_last_correlation_id',$correlation);if(!empty($p['schema_json'])){$schemas=is_array($p['schema_json'])&&isset($p['schema_json'][0])?$p['schema_json']:array($p['schema_json']);update_post_meta($saved,'_zica_posts_json_ld',$schemas);}if(!empty($p['featured_media_id']))set_post_thumbnail($saved,absint($p['featured_media_id']));$this->discovery->schedule_refresh(5);return rest_ensure_response(array('success'=>true,'post_id'=>$saved,'permalink'=>get_permalink($saved),'correlation_id'=>$correlation,'content_hash'=>$hash,'echo_suppressed'=>true));}
 public function media($request){$p=$request->get_json_params();$p=is_array($p)?$p:array();$data=isset($p['image_data'])?(string)$p['image_data']:'';$filename=sanitize_file_name(isset($p['filename'])?$p['filename']:'zica-media.png');if(0!==strpos($data,'data:image/'))return new WP_Error('zica_media_invalid','image_data deve ser Data URL de imagem.',array('status'=>400));$parts=explode(',',$data,2);$bytes=isset($parts[1])?base64_decode($parts[1],true):false;if(false===$bytes||strlen($bytes)>8*1024*1024)return new WP_Error('zica_media_size','Imagem inválida ou maior que 8MB.',array('status'=>400));$upload=wp_upload_bits($filename,null,$bytes);if(!empty($upload['error']))return new WP_Error('zica_media_upload',$upload['error'],array('status'=>500));$type=wp_check_filetype($upload['file']);if(!$type['type']||0!==strpos($type['type'],'image/')){@unlink($upload['file']);return new WP_Error('zica_media_type','Tipo de arquivo de imagem não permitido.',array('status'=>400));}$attachment=wp_insert_attachment(array('post_mime_type'=>$type['type'],'post_title'=>sanitize_text_field(pathinfo($filename,PATHINFO_FILENAME)),'post_status'=>'inherit'),$upload['file']);if(is_wp_error($attachment))return $attachment;require_once ABSPATH.'wp-admin/includes/image.php';$meta=wp_generate_attachment_metadata($attachment,$upload['file']);wp_update_attachment_metadata($attachment,$meta);if(!empty($p['alt_text']))update_post_meta($attachment,'_wp_attachment_image_alt',sanitize_text_field($p['alt_text']));return rest_ensure_response(array('success'=>true,'data'=>array('id'=>$attachment,'url'=>wp_get_attachment_url($attachment))));}
}
